#define DFC_TEXT_STORE_SIZE 128

enum DfcCustomEvent {
    // Reserve first 100 events for button types and indexes, starting from 0
    DfcCustomEventReserved = 100,

    DfcCustomEventViewExit,
    DfcCustomEventTextInputDone,
    // Read/write card events
    DfcCustomEventPollerError,
    DfcCustomEventPollerSuccess,
    // Events during emulating or reading
    DfcCustomEventEmulate,
    DfcCustomEventAppSelected,
    DfcCustomEventAuthenticated,
    DfcCustomEventFileRequested,
};

struct Dfc {
    bool is_debug_enabled;
    ViewDispatcher* view_dispatcher;
    Gui* gui;
    NotificationApp* notifications;
    SceneManager* scene_manager;

    char text_store[DFC_TEXT_STORE_SIZE + 1];
    FuriString* text_box_store;

    // Common Views
    Submenu* submenu;
    Popup* popup;
    Loading* loading;
    TextInput* text_input;
    TextBox* text_box;
    Widget* widget;
    FileBrowser* file_browser;

    Nfc* nfc;
    NfcListener* listener;
    NfcPoller* poller;
    NfcDevice* nfc_device;

    DfcCredential* credential;

    // NFC
    DfcEmulator* dfc_emulator;
    DfcReader* dfc_reader;

    // Set when Emulate was entered from "Blank Card" (main menu) rather than from a saved
    // credential's menu - routes the back button from Emulate to the Save flow instead of
    // to SavedMenu, so a card built up live during emulation (via WriteData from a real
    // reader) can be saved afterward.
    bool emulate_from_blank;
};

typedef enum {
    DfcViewMenu,
    DfcViewPopup,
    DfcViewLoading,
    DfcViewTextInput,
    DfcViewTextBox,
    DfcViewWidget,
    DfcViewFileBrowser,
} DfcView;

void dfc_text_store_set(Dfc* dfc, const char* text, ...);

void dfc_text_store_clear(Dfc* dfc);

void dfc_blink_start(Dfc* dfc);

void dfc_blink_stop(Dfc* dfc);

void dfc_show_loading_popup(void* context, bool show);

// Radio transport for the engine, implemented in dfc_emulator_listener.c.
NfcCommand dfc_worker_listener_callback(NfcGenericEvent event, void* context);
